# Existing StreetProbeCi only. Preserve different legal wire strings; never normalize the input files.
function Convert-StreetFixtureSdkTimes($value){
 if($value-is[pscustomobject]){foreach($property in $value.PSObject.Properties){
  if($property.Name-cin@('editorStartedAt','captureWindowStartedAt','captureStageDeadlineAt','captureTotalDeadlineAt','captureAcknowledgedAt')-and$property.Value-is[string]-and$property.Value){
   $date=LLStreetTimestamp $property.Value
   if($property.Name-ceq'editorStartedAt'){$date=$date.ToUniversalTime()}else{$date=$date.ToOffset([TimeSpan]::FromHours(8))}
   $fraction=($date.Ticks%[TimeSpan]::TicksPerSecond).ToString('D7',[Globalization.CultureInfo]::InvariantCulture).TrimEnd('0')
   $property.Value=$date.ToString("yyyy-MM-dd'T'HH:mm:ss",[Globalization.CultureInfo]::InvariantCulture)+$(if($fraction){'.'+$fraction}else{''})+$(if($property.Name-ceq'editorStartedAt'){'Z'}else{$date.ToString('zzz',[Globalization.CultureInfo]::InvariantCulture)})
  }else{Convert-StreetFixtureSdkTimes $property.Value}
 }}elseif($value-is[array]){foreach($item in $value){Convert-StreetFixtureSdkTimes $item}}
}
function Test-StreetTimestampBoundary {
