 $report=$identity|ConvertTo-Json|ConvertFrom-Json -DateKind String;$report.editorStartedAt='2026-11-03T02:48:57.274386Z';$report|Add-Member capabilityVersion 'AI441-sorting45-clock-ack-v1'
 $old=Join-Path $PSScriptRoot 'StreetProbeManagedState.PreAI439.ps1.txt';$token=$null;$errorToken=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($old,[ref]$token,[ref]$errorToken)
 $fn=@($ast.FindAll({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]-and$n.Name-ceq'Street-AssertIdentity'},$true));Check ($fn.Count-eq1) 'Actual pre439 identity function selected from preserved old bytes'
 Reject {& {Invoke-Expression $fn[0].Extent.Text;Street-AssertIdentity $report $identity}} 'Actual old helper rejects .2743860Z versus .274386Z despite same instant'
 Street-AssertIdentity $report $identity;Check $true 'Actual new role identity accepts legal SDK tail-zero transport difference'
 foreach($pair in @(@('2026-11-03T02:48:57.2743860Z','2026-11-03T02:48:57.274386Z'),@('2026-11-03T02:48:57Z','2026-11-03T02:48:57.0000000+00:00'),@('2026-11-03T02:48:57.1234567Z','2026-11-03T10:48:57.1234567+08:00'),@('2026-11-03T02:48:57.1Z','2026-11-02T21:48:57.1000000-05:00'))){Check (LLStreetSameInstant $pair[0] $pair[1]) 'Strict same instant across allowed ISO precision/offset'}
 for($digits=0;$digits-le7;$digits++){$fraction='1234567'.Substring(0,$digits);$text='2026-11-03T02:48:57'+$(if($fraction){'.'+$fraction}else{''})+'Z';$base=[DateTimeOffset]::new(2026,11,3,2,48,57,[TimeSpan]::Zero);$ticks=if($fraction){[long]::Parse($fraction.PadRight(7,'0'))}else{0};Check ((LLStreetTimestamp $text).UtcDateTime.Ticks-eq$base.AddTicks($ticks).UtcDateTime.Ticks) 'Every0..7 digit precision preserves exact100ns UTC ticks'}
 foreach($value in @('2026-11-03T02:48:57.2743861Z','2026-11-03T02:48:57.2743859Z')){Check (-not(LLStreetSameInstant $value $identity.editorStartedAt)) 'Same PID start differing by one100ns tick is rejected';$copy=$report|ConvertTo-Json|ConvertFrom-Json -DateKind String;$copy.editorStartedAt=$value;Reject {Street-AssertIdentity $copy $identity} 'Actual role identity rejects one tick start drift'}
 foreach($value in @($null,'','2026-11-03T02:48:57','2026-11-03T02:48:57z','2026-11-03T02:48:57.12345678Z','2026-11-03T02:48:57.Z','2026-11-31T02:48:57Z','2026-02-29T00:00:00Z','2026-11-03T02:48:60Z','2026-11-03T02:48:57+14:01','2026-11-03T02:48:57+24:00','2026-11-03T02:48:57+08',' 2026-11-03T02:48:57Z','November 3 2026',([DateTime]::UtcNow),([DateTimeOffset]::UtcNow),42,$true)){Reject {LLStreetTimestamp $value} 'Actual parser rejects missing/invalid/type/precision/zone/calendar input'}
 Check (-not(LLStreetIdentityField 'runId' '2026-11-03T02:48:57.2743860Z' '2026-11-03T02:48:57.274386Z')) 'Only explicit editorStartedAt identity field gets time semantics'
 $receipt=[pscustomobject]@{startedAt='2026-11-03T02:48:57Z';finishedAt='2026-11-03T02:48:58Z'};$notice=[pscustomobject]@{stageDeadlineAt='2026-11-03T02:48:57.5000000Z';totalDeadlineAt='2026-11-03T10:48:57.500+08:00'}
 $ack=$report|ConvertTo-Json|ConvertFrom-Json -DateKind String;$ack|Add-Member pendingCapture $null;$ack|Add-Member captureReceiptSha256 ('A'*64);$ack|Add-Member captureAcknowledgedAt '2026-11-03T10:48:57.5+08:00'
 Street-AssertRolePayload 'captureAck' $ack $identity $null $notice $null $receipt ([pscustomobject]@{sha256='A'*64});Check $true 'Actual ACK accepts exact deadline with equivalent offset representation'
 $ack.captureAcknowledgedAt='2026-11-03T02:48:57.5000001Z';Reject {Street-AssertRolePayload 'captureAck' $ack $identity $null $notice $null $receipt ([pscustomobject]@{sha256='A'*64})} 'Actual ACK one tick beyond deadline rejects without tolerance'
 $bytes=$utf8.GetBytes('{"editorStartedAt":"2026-11-03T02:48:57.2743860Z","other":"2026-11-03T02:48:57.274386Z"}');$obj=LLJson $bytes;$sha=LLHash $bytes;$null=LLStreetSameInstant $obj.editorStartedAt $obj.other;Check ((LLHash $bytes)-ceq$sha-and$obj.editorStartedAt-ceq'2026-11-03T02:48:57.2743860Z'-and$obj.other-ceq'2026-11-03T02:48:57.274386Z') 'Comparison leaves original JSON strings and raw SHA unchanged'
 $oldConsumer=Join-Path $PSScriptRoot 'StreetTimestampConsumer.PreAI439.ps1.txt';$a=[Management.Automation.Language.Parser]::ParseFile($oldConsumer,[ref]$token,[ref]$errorToken);$oldCanonical=@($a.FindAll({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]-and$n.Name-ceq'LLCanonical'},$true));$newAst=[Management.Automation.Language.Parser]::ParseFile($hostScript,[ref]$token,[ref]$errorToken);$newCanonical=@($newAst.FindAll({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]-and$n.Name-ceq'LLCanonical'},$true));Check ($oldCanonical.Count-eq1-and$newCanonical.Count-eq1-and$oldCanonical[0].Extent.Text-ceq$newCanonical[0].Extent.Text) 'Global LLCanonical actual function bytes unchanged'
